create extension if not exists pgcrypto;
create table public.communities(id uuid primary key default gen_random_uuid(),name text not null,province text,regency text,verification_status text not null default 'pending' check(verification_status in('pending','verified','rejected','suspended')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.community_members(community_id uuid not null references public.communities(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null default 'editor' check(role in('owner','editor','viewer')),created_at timestamptz not null default now(),primary key(community_id,user_id));
create table public.ich_reports(id uuid primary key default gen_random_uuid(),community_id uuid not null references public.communities(id) on delete cascade,slot_number smallint not null check(slot_number in(1,2)),ich_name text not null,category text,province text,regency text,latitude double precision,longitude double precision,access_level text not null default 'community' check(access_level in('public','community','restricted')),publication_status text not null default 'draft' check(publication_status in('draft','submitted','verified','published','archived')),latest_version_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(community_id,slot_number));
create table public.ich_report_versions(id uuid primary key default gen_random_uuid(),report_id uuid not null references public.ich_reports(id) on delete restrict,version_number integer not null check(version_number>0),payload jsonb not null check(jsonb_typeof(payload)='object'),submitted_by uuid references auth.users(id) on delete set null,change_note text,created_at timestamptz not null default now(),unique(report_id,version_number));
alter table public.ich_reports add constraint ich_reports_latest_version_fk foreign key(latest_version_id) references public.ich_report_versions(id) deferrable initially deferred;
create index idx_reports_community on public.ich_reports(community_id);create index idx_reports_geo on public.ich_reports(province,regency);create index idx_versions_report_date on public.ich_report_versions(report_id,created_at desc);
alter table public.communities enable row level security;alter table public.community_members enable row level security;alter table public.ich_reports enable row level security;alter table public.ich_report_versions enable row level security;
create policy "community members can view their communities" on public.communities for select to authenticated using(exists(select 1 from public.community_members m where m.community_id=communities.id and m.user_id=(select auth.uid())));
create policy "members can view own roster" on public.community_members for select to authenticated using(user_id=(select auth.uid()) or exists(select 1 from public.community_members m where m.community_id=community_members.community_id and m.user_id=(select auth.uid())));
create policy "members can read own reports" on public.ich_reports for select to authenticated using(exists(select 1 from public.community_members m where m.community_id=ich_reports.community_id and m.user_id=(select auth.uid())));
create policy "editors can insert reports" on public.ich_reports for insert to authenticated with check(exists(select 1 from public.community_members m where m.community_id=ich_reports.community_id and m.user_id=(select auth.uid()) and m.role in('owner','editor')));
create policy "editors can update reports" on public.ich_reports for update to authenticated using(exists(select 1 from public.community_members m where m.community_id=ich_reports.community_id and m.user_id=(select auth.uid()) and m.role in('owner','editor'))) with check(exists(select 1 from public.community_members m where m.community_id=ich_reports.community_id and m.user_id=(select auth.uid()) and m.role in('owner','editor')));
create policy "members can read report history" on public.ich_report_versions for select to authenticated using(exists(select 1 from public.ich_reports r join public.community_members m on m.community_id=r.community_id where r.id=ich_report_versions.report_id and m.user_id=(select auth.uid())));
create policy "editors can append history" on public.ich_report_versions for insert to authenticated with check(submitted_by=(select auth.uid()) and exists(select 1 from public.ich_reports r join public.community_members m on m.community_id=r.community_id where r.id=ich_report_versions.report_id and m.user_id=(select auth.uid()) and m.role in('owner','editor')));
create or replace function public.submit_ich_report(p_report_id uuid,p_payload jsonb,p_change_note text default null) returns public.ich_report_versions language plpgsql security invoker set search_path='' as $$ declare v_report public.ich_reports;v_version integer;v_snapshot public.ich_report_versions; begin if auth.uid() is null then raise exception 'Authentication required';end if;if jsonb_typeof(p_payload)<>'object' then raise exception 'Payload must be a JSON object';end if;select r.* into v_report from public.ich_reports r where r.id=p_report_id and exists(select 1 from public.community_members m where m.community_id=r.community_id and m.user_id=auth.uid() and m.role in('owner','editor')) for update;if not found then raise exception 'Report not found or access denied';end if;select coalesce(max(version_number),0)+1 into v_version from public.ich_report_versions where report_id=p_report_id;insert into public.ich_report_versions(report_id,version_number,payload,submitted_by,change_note) values(p_report_id,v_version,p_payload,auth.uid(),p_change_note) returning * into v_snapshot;update public.ich_reports set latest_version_id=v_snapshot.id,ich_name=coalesce(p_payload#>>'{report,ich_name}',ich_name),updated_at=now() where id=p_report_id;return v_snapshot;end;$$;
revoke all on function public.submit_ich_report(uuid,jsonb,text) from public,anon;grant execute on function public.submit_ich_report(uuid,jsonb,text) to authenticated;
create or replace view public.public_ich_dashboard with(security_invoker=true) as select r.id,r.ich_name,r.category,r.province,r.regency,r.latitude,r.longitude,r.updated_at,c.name community_name from public.ich_reports r join public.communities c on c.id=r.community_id where r.publication_status='published' and r.access_level='public' and c.verification_status='verified';
grant select on public.public_ich_dashboard to anon,authenticated;